-- Migration: Replace General Handbook chapter sources with h2 subsections
-- Generated from local dev DB; safe to run against any state of the handbook collection.

SET @cid = '49dafe5a-1bf9-4ecb-9a18-2ea91b608c5f';
SET @uid = (SELECT userID FROM study_collection WHERE collectionID = '49dafe5a-1bf9-4ecb-9a18-2ea91b608c5f' LIMIT 1);

-- Step 1: Remove any existing subsection rows (url contains #)
DELETE FROM study_source WHERE collectionID = @cid AND url LIKE '%#%';

-- Step 2: Soft-delete any original chapter sources still alive (title NOT NULL, url without #)
SELECT sourceID, @cid, @uid, NULL, 0
FROM study_source ss
WHERE collectionID = @cid
  AND ss.id = (SELECT MAX(s2.id) FROM study_source s2 WHERE s2.sourceID = ss.sourceID)
  AND ss.title IS NOT NULL
  AND (ss.url IS NULL OR ss.url NOT LIKE '%#%')
  AND ss.category IS NOT NULL;

-- Step 3: Insert 282 subsection sources
